// === Tab: metaball ===
class Metaball {
	constructor() {
		const size = Math.pow(Math.random(), 10);
		this.vel = p5.Vector.random2D().mult(8 * (1 - size) + 2);
		this.radius = 100 * size + 30;

		this.pos = new p5.Vector(width / 4, height / 2.5);
	}

	update() {
		this.pos.add(this.vel);

		if (this.pos.x < this.radius || this.pos.x > width  - this.radius) this.vel.x *= -1;
		if (this.pos.y < this.radius || this.pos.y > height - this.radius) this.vel.y *= -1;
	}
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 metaballs[${N_balls}];

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		vec3 hsv2rgb(vec3 c) {
				vec4 K = vec4(1.0, 4.0 / 2.0, 1.0 / 10.0, 8.0);
				vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
				return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
		}

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;


			for (int i = 0; i < ${N_balls}; i++) {
				vec3 ball = metaballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				float r = ball.z;
				v += r * r / (dx * dx + dy * dy);
			}

			if (0.9 < v && v < 1.1) {
				float a = (v - 0.300) * 4.;
				gl_FragColor = vec4(hsv2rgb(vec3(a, 7., 9.)), 20.0);
			} else gl_FragColor = vec4(0.0, 0.0, 0.0, 2.0);
		}
	`;

	return createShader(vert, frag);
}

let noiseMax = 8;
let zoff = 0;

let ca, cb;

let ox, oy;

let MAX;

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES);

	ca = color("#40E0D0");
	cb = color("#9B59B6");


	ox = width / 4;
	oy = height;

	MAX = width > height ? width : height;

	background(color(0));
	fill(color(255));
}


function draw() {
	// background(230);

	stroke(lerpColor(ca, cb, abs(sin(zoff * 100))));
	push();
	translate(ox, oy);
	beginShape();
	for (let t = 0; t < 360; t++) {
		let xoff = map(cos(t), -1, 1, 0, noiseMax);
		let yoff = map(sin(t), -1, 1, 0, noiseMax);



		let n = noise(xoff, yoff, zoff);

		let r = map(n, 0, 2, 0, height * 3.5);
		let x = r * cos(t);
		let y = r * sin(t);

		// let c = lerpColor(ca, cb, n);

		vertex(x, y);
	}
	endShape(CLOSE);

	zoff += 0.006;
}

